const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '支点' },
      { kind: 'text', payload: '动力臂' },
      { kind: 'text', payload: '阻力臂' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var s = Math.min(W / 800, H / 600);
    var ox = (W - 800 * s) / 2;
    var oy = (H - 600 * s) / 2;
    function X(x) { return ox + x * s; }
    function Y(y) { return oy + y * s; }
    function P(x, y) { return [X(x), Y(y)]; }
    function pl(pts) {
      var arr = [];
      for (var i = 0; i < pts.length; i++) {
        arr.push(P(pts[i][0], pts[i][1]));
      }
      return visualSdk.polyline(arr);
    }
    function closed(pts) {
      return pl(pts).concat([['Z']]);
    }
    function seg(x1, y1, x2, y2) {
      var a = P(x1, y1);
      var b = P(x2, y2);
      return [['M', a[0], a[1]], ['L', b[0], b[1]]];
    }

    var hatch = [];
    for (var hx = 95; hx <= 705; hx += 60) {
      hatch = hatch.concat(seg(hx, 522, hx - 16, 540));
    }

    var ground = pl([[70, 522], [730, 522]]).concat(hatch);

    var rock = closed([
      [505, 522], [513, 462], [532, 422], [556, 406],
      [584, 412], [606, 446], [616, 480], [620, 522]
    ]);

    var fulcrum = closed([[376, 522], [420, 414], [464, 522]]);

    var lever = pl([[140, 438], [558, 402]]);

    var effortArrow = seg(140, 332, 140, 422)
      .concat(seg(131, 398, 140, 422))
      .concat(seg(149, 398, 140, 422));

    var armEffort = seg(140, 300, 420, 300)
      .concat(seg(152, 293, 140, 300))
      .concat(seg(152, 307, 140, 300))
      .concat(seg(408, 293, 420, 300))
      .concat(seg(408, 307, 420, 300))
      .concat(seg(140, 290, 140, 312))
      .concat(seg(420, 290, 420, 312));

    var armResist = seg(420, 300, 558, 300)
      .concat(seg(432, 293, 420, 300))
      .concat(seg(432, 307, 420, 300))
      .concat(seg(546, 293, 558, 300))
      .concat(seg(546, 307, 558, 300))
      .concat(seg(420, 290, 420, 312))
      .concat(seg(558, 290, 558, 312));

    return {
      schemaVersion: 1,
      sceneId: 'crowbar-rock',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'ground', commands: ground },
        { id: 'rock', commands: rock },
        { id: 'fulcrum', commands: fulcrum },
        { id: 'lever', commands: lever },
        { id: 'effortArrow', commands: effortArrow },
        { id: 'armEffort', commands: armEffort },
        { id: 'armResist', commands: armResist }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'ground', fill: '#3a3f4b', stroke: { width: 5 * s, cap: 'round' } },
          { type: 'path', pathId: 'rock', fill: '#8d9299', stroke: { width: 3 * s, join: 'round' } },
          { type: 'path', pathId: 'fulcrum', fill: '#2f3a4a', stroke: { width: 3 * s, join: 'round' } },
          { type: 'path', pathId: 'lever', fill: '#6b4f33', stroke: { width: 16 * s, cap: 'round' } },
          { type: 'path', pathId: 'effortArrow', fill: '#1f2733', stroke: { width: 5 * s, cap: 'round' } },
          { type: 'path', pathId: 'armEffort', fill: '#b23b3b', stroke: { width: 3 * s, cap: 'round' } },
          { type: 'path', pathId: 'armResist', fill: '#b23b3b', stroke: { width: 3 * s, cap: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: X(352), y: Y(492) }, hAlign: 'right', vAlign: 'middle', color: '#1f2733' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: X(280), y: Y(286) }, hAlign: 'center', vAlign: 'bottom', color: '#b23b3b' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: X(489), y: Y(286) }, hAlign: 'center', vAlign: 'bottom', color: '#b23b3b' }
        ]
      }
    };
  }
};
